package OOPS.Encapsulation;public class Student {    private int age;    private String name;    public String getName() {        return name;    }    public void setName(String name) {        this.name = name;    }    public void setage(int age){        if(age<0){            age=0;        }        this.age=age;    }    public int getage(){        return age;    }}class details{    public static void main(String[] args) {        Student s1=new Student();        s1.setage(20);        s1.setName("aman");        System.out.println(s1.getage());        System.out.println(s1.getName());    }}